C: Go to School writer: beet
与えられた順列に対し、各要素のソート後のインデックスを求める問題です。
rev[Ai] = i となるような配列rev を求めればいいです。
以下はC++ における実装例です。
1 #include <iostream>
2 #include <vector>
3 using namespace std;
4 int main(){
5
int N;
6
cin>>N;
7
vector<int> A(N);
8
for(int i=0;i<N;i++) cin>>A[i];
9
10
vector<int> rev(N);
11
for(int i=0;i<N;i++) rev[A[i]-1]=i+1;
12
for(int i=0;i<N;i++) cout<<rev[i]<<endl;
13
return 0;
14 }
